USE smarttcm;

-- 解表药补充
INSERT INTO questions (competition, question_type, question_category, content_category, question, answer, answer_only, knowledge_point, primary_project, secondary_project, core_connotation, text_level) VALUES
('中医知识库','中药','中药学','解表药','荆芥的功效与主治是什么？','解表散风、透疹消疮、炒炭止血。主治感冒发热、头痛、麻疹不透、衄血便血。','荆芥辛微温，归肺肝经。为解表散风之常用药，长于发表散风，透疹止痒。炒炭后收敛止血。','荆芥；解表散风；透疹；炒炭止血','中药学','解表药','荆芥辛微温，善解表散风、透疹止痒，炒炭兼能止血','入门'),
('中医知识库','中药','中药学','解表药','防风的功效与主治是什么？','祛风解表、胜湿止痛、止痉。主治感冒头痛、风湿痹痛、风疹瘙痒、破伤风。','防风辛甘微温，归膀胱肝脾经。为治风之通用药，既能祛风寒，又能祛风湿。','防风；祛风解表；胜湿止痛；治风通用','中药学','解表药','防风为治风通用药，既能祛风解表，又能胜湿止痛','入门'),
('中医知识库','中药','中药学','解表药','羌活的功效与主治是什么？','解表散寒、祛风胜湿、止痛。主治风寒感冒、头痛身疼、风寒湿痹。','羌活辛苦温，归膀胱肾经。善治上半身风寒湿痹，为太阳经之引经药。','羌活；解表散寒；祛风胜湿；上半身痹痛','中药学','解表药','羌活善治上半身风寒湿痹及太阳头痛','入门'),
('中医知识库','中药','中药学','解表药','白芷的功效与主治是什么？','解表散寒、祛风止痛、通鼻窍、燥湿止带、消肿排脓。主治风寒感冒、头痛鼻渊、牙痛、带下。','白芷辛温，归肺胃大肠经。善治阳明头痛，为治鼻渊之要药。','白芷；祛风止痛；通鼻窍；阳明头痛；鼻渊','中药学','解表药','白芷善治阳明头痛和鼻渊，为通窍止痛之要药','入门'),
('中医知识库','中药','中药学','解表药','细辛的功效与主治是什么？','祛风散寒、通窍止痛、温肺化饮。主治风寒感冒、头痛牙痛、鼻渊鼻塞、痰饮喘咳。','细辛辛温，归肺肾经。芳香走窜，善通鼻窍止痛。用量不宜过大，"细辛不过钱"。','细辛；祛风散寒；通窍止痛；温肺化饮；细辛不过钱','中药学','解表药','细辛善通窍止痛温肺化饮，用量须谨慎不过钱','中级'),
('中医知识库','中药','中药学','解表药','薄荷的功效与主治是什么？','疏散风热、清利头目、利咽透疹、疏肝行气。主治风热感冒、头痛目赤、咽喉肿痛、麻疹不透。','薄荷辛凉，归肺肝经。芳香辟秽，善疏散风热、清利头目咽喉。不宜久煎。','薄荷；疏散风热；清利头目；利咽透疹；不宜久煎','中药学','解表药','薄荷辛凉芳香，善疏散风热、清利头目','入门'),
('中医知识库','中药','中药学','解表药','牛蒡子的功效与主治是什么？','疏散风热、宣肺透疹、解毒利咽。主治风热感冒、咽喉肿痛、麻疹不透、痈肿疮毒。','牛蒡子辛苦寒，归肺胃经。善于清热解毒、利咽透疹，为治咽喉肿痛之常用药。','牛蒡子；疏散风热；宣肺透疹；解毒利咽','中药学','解表药','牛蒡子善清热解毒利咽，为治风热咽痛之要药','入门'),
('中医知识库','中药','中药学','解表药','蝉蜕的功效与主治是什么？','疏散风热、利咽透疹、明目退翳、解痉。主治风热感冒、咽痛音哑、麻疹不透、目赤翳障、惊风抽搐。','蝉蜕甘寒，归肺肝经。善于疏散风热、明目退翳，又能凉肝熄风止痉。','蝉蜕；疏散风热；明目退翳；熄风止痉','中药学','解表药','蝉蜕善疏散风热明目退翳，又能熄风止痉','入门'),
('中医知识库','中药','中药学','解表药','桑叶的功效与主治是什么？','疏散风热、清肺润燥、平肝明目。主治风热感冒、肺热燥咳、头晕头痛、目赤昏花。','桑叶甘苦寒，归肺肝经。善于疏散风热、清肺润燥。经霜后采收者质量更佳。','桑叶；疏散风热；清肺润燥；平肝明目','中药学','解表药','桑叶善清肺润燥平肝明目，为秋令常用药','入门'),
('中医知识库','中药','中药学','解表药','菊花的功效与主治是什么？','疏散风热、平肝明目、清热解毒。主治风热感冒、头痛眩晕、目赤肿痛、疮痈肿毒。','菊花辛甘苦微寒，归肺肝经。白菊花偏于平肝明目，野菊花偏于清热解毒。','菊花；疏散风热；平肝明目；清热解毒','中药学','解表药','菊花善平肝明目清热解毒，为常用的药茶品种','入门'),
('中医知识库','中药','中药学','解表药','柴胡的功效与主治是什么？','解表退热、疏肝解郁、升举阳气。主治感冒发热、少阳证、肝郁气滞、气虚下陷。','柴胡苦辛微寒，归肝胆经。为治少阳证之要药，善疏解半表半里之邪。又能疏肝解郁。','柴胡；解表退热；疏肝解郁；升举阳气；少阳证','中药学','解表药','柴胡为治少阳证之要药，善疏肝解郁、升举阳气','入门'),
('中医知识库','中药','中药学','解表药','葛根的功效与主治是什么？','解肌退热、透疹、生津止渴、升阳止泻。主治外感发热、项背强痛、麻疹不透、热病口渴、脾虚泄泻。','葛根甘辛凉，归脾肺胃经。善治项背强痛，为治表证发热、颈项强急之要药。','葛根；解肌退热；生津止渴；升阳止泻；项背强痛','中药学','解表药','葛根善解肌退热、升阳生津，为治项背强痛之要药','入门'),
('中医知识库','中药','中药学','解表药','升麻的功效与主治是什么？','发表透疹、清热解毒、升举阳气。主治风热头痛、麻疹不透、齿痛口疮、气虚下陷。','升麻辛微甘微寒，归肺脾胃大肠经。善升举脾胃清阳之气，又能清热解毒。','升麻；发表透疹；清热解毒；升举阳气','中药学','解表药','升麻善升举阳气，为治疗气虚下陷之辅助药','入门'),
('中医知识库','中药','中药学','解表药','生姜的功效与主治是什么？','解表散寒、温中止呕、化痰止咳。主治风寒感冒、胃寒呕吐、寒痰咳嗽。','生姜辛微温，归肺脾胃经。为"呕家圣药"，善于温胃止呕。又能解半夏、天南星毒。','生姜；解表散寒；温中止呕；呕家圣药','中药学','解表药','生姜为呕家圣药，善温胃止呕解表散寒','入门'),

-- 清热药补充
('中医知识库','中药','中药学','清热药','知母的功效与主治是什么？','清热泻火、滋阴润燥。主治气分实热、肺热咳嗽、阴虚发热、骨蒸潮热、内热消渴。','知母苦甘寒，归肺胃肾经。善清肺胃之火，又能滋阴润燥。与黄柏相须为用，善治阴虚火旺。','知母；清热泻火；滋阴润燥；阴虚火旺','中药学','清热药','知母善清热泻火滋阴润燥，为清补兼施之品','入门'),
('中医知识库','中药','中药学','清热药','栀子的功效与主治是什么？','泻火除烦、清热利湿、凉血解毒。主治热病心烦、湿热黄疸、血热出血、热毒疮疡。','栀子苦寒，归心肺三焦经。善清泻三焦之火，导湿热从小便而出。为治热病心烦之要药。','栀子；泻火除烦；清热利湿；凉血解毒','中药学','清热药','栀子善泻三焦之火，为治热病心烦之要药','入门'),
('中医知识库','中药','中药学','清热药','夏枯草的功效与主治是什么？','清肝泻火、明目散结。主治目赤肿痛、头痛眩晕、瘰疬瘿瘤、乳痈肿痛。','夏枯草辛苦寒，归肝胆经。善清肝火、散郁结，为治肝火上炎之目赤肿痛及瘰疬之要药。','夏枯草；清肝泻火；明目散结；瘰疬','中药学','清热药','夏枯草善清肝火散郁结，为治肝热目赤瘰疬之要药','入门'),
('中医知识库','中药','中药学','清热药','决明子的功效与主治是什么？','清热明目、润肠通便。主治目赤涩痛、羞明多泪、头痛眩晕、肠燥便秘。','决明子甘苦咸微寒，归肝大肠经。善清肝明目，为治肝热目赤之常用药。又能润肠通便。','决明子；清热明目；润肠通便','中药学','清热药','决明子善清肝明目润肠通便，为常用养生茶药','入门'),
('中医知识库','中药','中药学','清热药','苦参的功效与主治是什么？','清热燥湿、杀虫利尿。主治湿热泻痢、黄疸、带下、阴痒、湿疹瘙痒。','苦参苦寒，归心肝胃大肠膀胱经。善于清热燥湿、祛风杀虫，为治皮肤瘙痒之常用药。','苦参；清热燥湿；杀虫止痒；皮肤瘙痒','中药学','清热药','苦参善清热燥湿杀虫，为治疗皮肤瘙痒之常用药','入门'),
('中医知识库','中药','中药学','清热药','龙胆草的功效与主治是什么？','清热燥湿、泻肝胆火。主治湿热黄疸、阴肿阴痒、带下、肝火头痛、目赤耳聋。','龙胆草苦寒，归肝胆经。大苦大寒，善泻肝胆实火、清下焦湿热。为治肝火湿热之要药。','龙胆草；清热燥湿；泻肝胆火；肝火头痛','中药学','清热药','龙胆草大苦大寒，善泻肝胆实火、清下焦湿热','中级'),
('中医知识库','中药','中药学','清热药','连翘的功效与主治是什么？','清热解毒、消肿散结。主治风热感冒、温病初起、痈疮肿毒、瘰疬。','连翘苦微寒，归心肺小肠经。为清热解毒之要药，善治疮痈肿毒，有"疮家圣药"之称。','连翘；清热解毒；消肿散结；疮家圣药','中药学','清热药','连翘为疮家圣药，善清热解毒消肿散结','入门'),
('中医知识库','中药','中药学','清热药','蒲公英的功效与主治是什么？','清热解毒、消肿散结、利湿通淋。主治痈肿疔毒、乳痈、咽喉肿痛、热淋涩痛。','蒲公英苦甘寒，归肝胃经。善清热解毒，尤善治乳痈，为治疗热毒疮疡之常用药。','蒲公英；清热解毒；消肿散结；乳痈','中药学','清热药','蒲公英善清热解毒消痈散结，为治乳痈之要药','入门'),
('中医知识库','中药','中药学','清热药','鱼腥草的功效与主治是什么？','清热解毒、消痈排脓、利尿通淋。主治肺痈吐脓、痰热喘咳、热淋涩痛。','鱼腥草辛微寒，归肺经。为治肺痈之要药，善清肺热、消痈排脓。','鱼腥草；清热解毒；消痈排脓；肺痈','中药学','清热药','鱼腥草为治肺痈之要药，善清肺热消痈排脓','入门'),
('中医知识库','中药','中药学','清热药','白头翁的功效与主治是什么？','清热解毒、凉血止痢。主治热毒血痢、阴痒带下。','白头翁苦寒，归胃大肠经。为治热毒血痢之要药，善清肠中热毒。','白头翁；清热解毒；凉血止痢；热毒血痢','中药学','清热药','白头翁为治热毒血痢之要药，善清肠热止痢','入门'),
('中医知识库','中药','中药学','清热药','大青叶的功效与主治是什么？','清热解毒、凉血消斑。主治温病高热、神昏、发斑发疹、痄腮丹毒。','大青叶苦寒，归心肺胃经。善清热解毒、凉血消斑，为治温热病热入血分发斑之要药。','大青叶；清热解毒；凉血消斑；温毒发斑','中药学','清热药','大青叶善清热解毒凉血消斑，为治温毒发斑之要药','入门'),
('中医知识库','中药','中药学','清热药','穿心莲的功效与主治是什么？','清热解毒、凉血消肿。主治感冒发热、咽喉肿痛、口舌生疮、痈肿疮疡、泄泻痢疾。','穿心莲苦寒，归心肺大肠膀胱经。善于清热解毒，对多种感染性疾病有效。','穿心莲；清热解毒；凉血消肿；抗感染','中药学','清热药','穿心莲善清热解毒，为广谱抗菌中药','入门'),
('中医知识库','中药','中药学','清热药','青蒿的功效与主治是什么？','清透虚热、凉血除蒸、解暑截疟。主治温邪伤阴、夜热早凉、阴虚发热、暑热外感、疟疾。','青蒿苦辛寒，归肝胆经。善于清虚热、退骨蒸，为治阴虚发热之要药。又能截疟。','青蒿；清透虚热；凉血除蒸；截疟；青蒿素','中药学','清热药','青蒿善清虚热截疟，其提取物青蒿素获诺贝尔奖','中级'),

-- 泻下药补充
('中医知识库','中药','中药学','泻下药','芒硝的功效与主治是什么？','泻下攻积、润燥软坚、清热消肿。主治实热积滞、大便燥结、咽痛口疮、目赤肿痛。','芒硝咸苦寒，归胃大肠经。善于润燥软坚泻下，与大黄相须为用。外用可清热消肿。','芒硝；泻下软坚；清热消肿；润燥通便','中药学','泻下药','芒硝善润燥软坚泻下，为治实热燥结之要药','入门'),
('中医知识库','中药','中药学','泻下药','火麻仁的功效与主治是什么？','润肠通便。主治肠燥便秘，尤宜老人、产妇及体弱者之便秘。','火麻仁甘平，归脾大肠经。药性平和，为常用的润下药，善治肠燥便秘。','火麻仁；润肠通便；肠燥便秘；性平','中药学','泻下药','火麻仁药性平和，为常用润下通便之品','入门'),
('中医知识库','中药','中药学','泻下药','番泻叶的功效与主治是什么？','泻下通便。主治热结便秘、腹水肿胀。','番泻叶甘苦寒，归大肠经。为峻下通便之品，小量可缓下，大量可峻下。不宜久煎。','番泻叶；泻下通便；热结便秘；不宜久煎','中药学','泻下药','番泻叶为峻下通便之品，用量不同则缓下或峻下','入门'),

-- 祛风湿药补充
('中医知识库','中药','中药学','祛风湿药','威灵仙的功效与主治是什么？','祛风除湿、通络止痛。主治风湿痹痛、肢体麻木、筋脉拘挛、骨鲠咽喉。','威灵仙辛咸温，归膀胱经。善祛风除湿、通络止痛，为治风湿痹痛之要药。又能软化骨鲠。','威灵仙；祛风除湿；通络止痛；软化骨鲠','中药学','祛风湿药','威灵仙善祛风通络止痛，又能软化骨鲠','入门'),
('中医知识库','中药','中药学','祛风湿药','秦艽的功效与主治是什么？','祛风湿、清湿热、止痹痛、退虚热。主治风湿痹痛、骨蒸潮热、湿热黄疸。','秦艽辛苦平，归胃肝胆经。为"风药中之润剂"，既能祛风除湿，又能清退虚热。','秦艽；祛风湿；清湿热；退虚热；风药润剂','中药学','祛风湿药','秦艽为风药中之润剂，祛风除湿兼退虚热','入门'),
('中医知识库','中药','中药学','祛风湿药','木瓜的功效与主治是什么？','舒筋活络、和胃化湿。主治风湿痹痛、筋脉拘挛、脚气肿痛、吐泻转筋。','木瓜酸温，归肝脾经。善于舒筋活络，为治筋脉拘挛之要药。又能化湿和胃。','木瓜；舒筋活络；和胃化湿；筋脉拘挛','中药学','祛风湿药','木瓜善舒筋活络，为治筋脉拘挛之要药','入门'),
('中医知识库','中药','中药学','祛风湿药','桑寄生的功效与主治是什么？','祛风湿、补肝肾、强筋骨、安胎。主治风湿痹痛、腰膝酸软、胎动不安。','桑寄生苦甘平，归肝肾经。既能祛风湿，又能补肝肾、强筋骨。为治风湿痹痛兼肝肾不足之要药。','桑寄生；祛风湿；补肝肾；强筋骨；安胎','中药学','祛风湿药','桑寄生祛风湿兼补肝肾，为标本兼治之品','入门'),

-- 化湿药补充
('中医知识库','中药','中药学','化湿药','厚朴的功效与主治是什么？','燥湿消痰、下气除满。主治湿滞伤中、脘痞吐泻、食积气滞、腹胀便秘、痰饮喘咳。','厚朴苦辛温，归脾胃肺大肠经。为消除胀满之要药，善行气燥湿除满。','厚朴；燥湿消痰；下气除满；消除胀满','中药学','化湿药','厚朴为消除胀满之要药，善行气燥湿消痰','入门'),
('中医知识库','中药','中药学','化湿药','砂仁的功效与主治是什么？','化湿开胃、温脾止泻、理气安胎。主治湿浊中阻、脘痞不饥、脾胃虚寒、呕吐泄泻、胎动不安。','砂仁辛温，归脾胃肾经。芳香温通，善于化湿行气、温脾止泻，又能安胎。','砂仁；化湿开胃；温脾止泻；理气安胎','中药学','化湿药','砂仁芳香温通，善化湿行气温脾安胎','入门'),
('中医知识库','中药','中药学','化湿药','白豆蔻的功效与主治是什么？','化湿行气、温中止呕。主治湿阻中焦、脾胃气滞、胸闷不饥、胃寒呕吐。','白豆蔻辛温，归肺脾胃经。芳香化湿、行气宽中，尤善治胃寒呕吐。','白豆蔻；化湿行气；温中止呕；胃寒呕吐','中药学','化湿药','白豆蔻芳香化湿，尤善温中止呕','入门'),

-- 利水渗湿药补充
('中医知识库','中药','中药学','利水渗湿药','薏苡仁的功效与主治是什么？','利水渗湿、健脾止泻、除痹排脓。主治水肿、脚气、小便不利、脾虚泄泻、湿痹拘挛。','薏苡仁甘淡凉，归脾胃肺经。药性平和，既能利水渗湿，又能健脾。为药食两用之品。','薏苡仁；利水渗湿；健脾止泻；药食两用','中药学','利水渗湿药','薏苡仁药性平和，利水渗湿兼能健脾，为药食两用佳品','入门'),
('中医知识库','中药','中药学','利水渗湿药','泽泻的功效与主治是什么？','利水渗湿、泄热。主治水肿胀满、小便不利、泄泻尿少、痰饮眩晕、高脂血症。','泽泻甘寒，归肾膀胱经。善于利水渗湿，又能泄肾经之虚火。','泽泻；利水渗湿；泄热；痰饮眩晕','中药学','利水渗湿药','泽泻善利水渗湿泄热，为常用的利水药','入门'),
('中医知识库','中药','中药学','利水渗湿药','茵陈蒿的功效与主治是什么？','清利湿热、利胆退黄。主治湿热黄疸、小便不利、湿温暑湿。','茵陈蒿苦辛微寒，归脾胃肝胆经。为治黄疸之要药，善清利湿热、利胆退黄。','茵陈蒿；清利湿热；利胆退黄；黄疸要药','中药学','利水渗湿药','茵陈蒿为治黄疸之要药，善清利湿热利胆退黄','入门'),
('中医知识库','中药','中药学','利水渗湿药','金钱草的功效与主治是什么？','利湿退黄、利尿通淋、解毒消肿。主治湿热黄疸、石淋热淋、肝胆结石、痈肿疔疮。','金钱草甘咸微寒，归肝胆肾膀胱经。善于利湿退黄、利尿通淋，为治结石之要药。','金钱草；利湿退黄；利尿通淋；结石要药','中药学','利水渗湿药','金钱草为治结石之要药，善利湿退黄利尿通淋','入门'),
('中医知识库','中药','中药学','利水渗湿药','滑石的功效与主治是什么？','利尿通淋、清热解暑、收湿敛疮。主治热淋石淋、暑热烦渴、湿温尿赤、外治湿疹痱子。','滑石甘淡寒，归膀胱肺经。善于清热利湿，为治暑湿之常用药。外用可收湿敛疮。','滑石；利尿通淋；清热解暑；收湿敛疮','中药学','利水渗湿药','滑石善清热利湿解暑，外用收湿敛疮','入门'),

-- 温里药补充
('中医知识库','中药','中药学','温里药','肉桂的功效与主治是什么？','补火助阳、引火归元、散寒止痛、温通经脉。主治肾阳不足、阳痿宫冷、腹痛寒疝、腰痛。','肉桂辛甘大热，归肾脾心肝经。善补命门之火，为温补肾阳之要药。与附子相须为用。','肉桂；补火助阳；引火归元；散寒止痛；补命门火','中药学','温里药','肉桂善补命门之火、引火归元，为温补肾阳之要药','中级'),
('中医知识库','中药','中药学','温里药','吴茱萸的功效与主治是什么？','散寒止痛、降逆止呕、助阳止泻。主治厥阴头痛、寒疝腹痛、寒湿脚气、经行腹痛、呕吐吞酸。','吴茱萸辛苦热，归肝脾胃肾经。性热燥烈，善散厥阴之寒、降厥阴之逆。有小毒。','吴茱萸；散寒止痛；降逆止呕；厥阴头痛','中药学','温里药','吴茱萸性热燥烈，善散厥阴之寒降逆止呕','中级'),
('中医知识库','中药','中药学','温里药','丁香的功效与主治是什么？','温中降逆、补肾助阳。主治胃寒呕吐呃逆、脘腹冷痛、肾虚阳痿。','丁香辛温，归脾胃肾经。善于温中降逆，为治胃寒呕吐呃逆之要药。畏郁金。','丁香；温中降逆；补肾助阳；呃逆要药；畏郁金','中药学','温里药','丁香善温中降逆，为治胃寒呕呃之要药','入门'),

-- 理气药补充
('中医知识库','中药','中药学','理气药','香附的功效与主治是什么？','疏肝理气、调经止痛。主治肝郁气滞、胸胁胀痛、疝气疼痛、乳房胀痛、月经不调。','香附辛苦平，归肝脾三焦经。为理气解郁之要药，善疏肝理气、调经止痛。有"气病之总司"之称。','香附；疏肝理气；调经止痛；气病总司','中药学','理气药','香附为理气解郁之要药，有气病总司之称','入门'),
('中医知识库','中药','中药学','理气药','木香的功效与主治是什么？','行气止痛、健脾消食。主治胸胁脘腹胀痛、泻痢后重、食积不消。','木香辛苦温，归脾胃大肠三焦胆经。善行肠胃气滞而止痛，为治泻痢后重之要药。','木香；行气止痛；健脾消食；泻痢后重','中药学','理气药','木香善行肠胃气滞止痛，为治泻痢后重之要药','入门'),
('中医知识库','中药','中药学','理气药','枳实的功效与主治是什么？','破气消积、化痰散痞。主治积滞内停、痞满胀痛、泻痢后重、大便不通、痰滞气阻。','枳实辛苦微寒，归脾胃大肠经。善于破气消积、化痰除痞。药力峻猛，不宜过量。','枳实；破气消积；化痰散痞；药力峻猛','中药学','理气药','枳实药力峻猛，善破气消积化痰散痞','入门'),
('中医知识库','中药','中药学','理气药','薤白的功效与主治是什么？','通阳散结、行气导滞。主治胸痹疼痛、痰饮咳喘、泻痢后重。','薤白辛苦温，归肺心胃大肠经。善于通阳散结，为治胸痹之要药。','薤白；通阳散结；行气导滞；胸痹要药','中药学','理气药','薤白善通阳散结，为治胸痹之要药','入门'),
('中医知识库','中药','中药学','理气药','沉香的功效与主治是什么？','行气止痛、温中止呕、纳气平喘。主治胸腹胀痛、胃寒呕吐、肾虚气喘。','沉香辛苦微温，归脾胃肾经。善于行气止痛、温中降逆，又能纳气平喘。为珍贵药材。','沉香；行气止痛；温中止呕；纳气平喘','中药学','理气药','沉香善行气止痛纳气平喘，为珍贵药材','中级'),

-- 消食药补充
('中医知识库','中药','中药学','消食药','神曲的功效与主治是什么？','消食和胃。主治饮食积滞、脘腹胀满、食少纳呆。','神曲甘辛温，归脾胃经。善于消食和胃，为消食化积之常用药。','神曲；消食和胃；饮食积滞','中药学','消食药','神曲善消食和胃，为消食化积之常用药','入门'),
('中医知识库','中药','中药学','消食药','麦芽的功效与主治是什么？','消食健胃、回乳消胀。主治米面薯芋食滞、断乳乳房胀痛。','麦芽甘平，归脾胃肝经。善于消化米面之积，又能回乳。生用疏肝，炒用消食。','麦芽；消食健胃；回乳消胀；消化淀粉类','中药学','消食药','麦芽善消米面之积，又能回乳消胀','入门'),
('中医知识库','中药','中药学','消食药','莱菔子的功效与主治是什么？','消食除胀、降气化痰。主治食积气滞、脘腹胀满、嗳气吞酸、咳嗽痰多。','莱菔子辛甘平，归脾胃肺经。善于消食化积、降气化痰。生用吐风痰，炒用消食下气。','莱菔子；消食除胀；降气化痰','中药学','消食药','莱菔子善消食除胀降气化痰，药食同源','入门'),
('中医知识库','中药','中药学','消食药','鸡内金的功效与主治是什么？','消食健胃、固精止遗、化结石。主治饮食积滞、小儿疳积、肾虚遗精、石淋胆结石。','鸡内金甘平，归脾胃小肠膀胱经。消食作用较强，又能固精止遗、化结石。','鸡内金；消食健胃；固精止遗；化结石','中药学','消食药','鸡内金消食力强，兼能固精通淋化石','入门'),

-- 止血药补充
('中医知识库','中药','中药学','止血药','白茅根的功效与主治是什么？','凉血止血、清热利尿。主治血热出血、热淋涩痛、水肿尿少、黄疸。','白茅根甘寒，归肺胃膀胱经。善于凉血止血、清热利尿。药性平和，为治血热出血之常用药物。','白茅根；凉血止血；清热利尿','中药学','止血药','白茅根药性平和，善凉血止血清热利尿','入门'),
('中医知识库','中药','中药学','止血药','地榆的功效与主治是什么？','凉血止血、解毒敛疮。主治便血痔血、血痢崩漏、水火烫伤、痈肿疮毒。','地榆苦酸微寒，归肝大肠经。善于凉血止血，尤宜下焦血热之便血、痔血。为治烫伤之要药。','地榆；凉血止血；解毒敛疮；烫伤要药','中药学','止血药','地榆善凉血止血解毒敛疮，为治下焦出血及烫伤之要药','入门'),
('中医知识库','中药','中药学','止血药','艾叶的功效与主治是什么？','温经止血、散寒止痛、调经安胎、外用祛湿止痒。主治虚寒性出血、腹中冷痛、月经不调、胎动不安。','艾叶辛苦温，归肝脾肾经。善于温经止血、散寒止痛，为治虚寒性出血之要药。又为艾灸的主要原料。','艾叶；温经止血；散寒止痛；艾灸原料','中药学','止血药','艾叶善温经止血散寒，又为艾灸之主要原料','入门'),
('中医知识库','中药','中药学','止血药','仙鹤草的功效与主治是什么？','收敛止血、止痢截疟、补虚。主治多种出血证、泻痢、脱力劳伤。','仙鹤草苦涩平，归心肺肝经。收敛止血作用较强，广泛用于各种出血证。又能补虚。','仙鹤草；收敛止血；止痢；补虚','中药学','止血药','仙鹤草收敛止血力强，广泛用于各种出血','入门'),

-- 活血化瘀药补充
('中医知识库','中药','中药学','活血化瘀药','桃仁的功效与主治是什么？','活血祛瘀、润肠通便、止咳平喘。主治经闭痛经、癥瘕痞块、肺痈肠痈、肠燥便秘。','桃仁苦甘平，归心肝大肠经。善于活血祛瘀，为治瘀血阻滞之常用药。又能润肠通便。','桃仁；活血祛瘀；润肠通便；瘀血阻滞','中药学','活血化瘀药','桃仁善活血祛瘀润肠，为治瘀血阻滞之常用药','入门'),
('中医知识库','中药','中药学','活血化瘀药','红花的功效与主治是什么？','活血通经、散瘀止痛。主治经闭痛经、胸痹心痛、血瘀腹痛、跌打损伤、疮疡肿痛。','红花辛温，归心肝经。善于活血通经、祛瘀止痛，为治瘀血阻滞之要药。少用养血，多用活血。','红花；活血通经；散瘀止痛；少用养血多用活血','中药学','活血化瘀药','红花善活血通经散瘀止痛，少用养血多用活血','入门'),
('中医知识库','中药','中药学','活血化瘀药','延胡索的功效与主治是什么？','活血、行气、止痛。主治胸痹心痛、脘腹疼痛、痛经、跌打肿痛。','延胡索辛苦温，归肝脾心经。善于活血行气止痛，为止痛之要药，"专治一身上下诸痛"。','延胡索；活血行气；止痛要药；一身上下诸痛','中药学','活血化瘀药','延胡索为止痛要药，善活血行气，治一身上下诸痛','入门'),
('中医知识库','中药','中药学','活血化瘀药','益母草的功效与主治是什么？','活血调经、利尿消肿、清热解毒。主治月经不调、痛经经闭、水肿尿少、疮疡肿毒。','益母草辛苦微寒，归肝心膀胱经。善于活血调经，为妇科经产之要药。','益母草；活血调经；利尿消肿；妇科要药','中药学','活血化瘀药','益母草为妇科经产要药，善活血调经利尿消肿','入门'),
('中医知识库','中药','中药学','活血化瘀药','牛膝的功效与主治是什么？','活血通经、补肝肾、强筋骨、利水通淋、引火下行。主治经闭痛经、腰膝酸痛、水肿、头痛眩晕。','牛膝苦甘酸平，归肝肾经。善于活血通经、补肝肾、强筋骨，又能引血下行。','牛膝；活血通经；补肝肾；引血下行','中药学','活血化瘀药','牛膝善活血通经补肝肾，又能引血下行','入门'),
('中医知识库','中药','中药学','活血化瘀药','鸡血藤的功效与主治是什么？','活血补血、调经止痛、舒筋活络。主治月经不调、痛经闭经、血虚萎黄、风湿痹痛。','鸡血藤苦甘温，归肝肾经。既能活血，又能补血，为活血补血之要药。','鸡血藤；活血补血；调经止痛；舒筋活络','中药学','活血化瘀药','鸡血藤既能活血又能补血，为活血补血之要药','入门'),
('中医知识库','中药','中药学','活血化瘀药','乳香的功效与主治是什么？','活血行气止痛、消肿生肌。主治胸痹心痛、胃脘疼痛、痛经经闭、跌打损伤、痈疽肿毒。','乳香辛苦温，归心肝脾经。善于活血行气止痛，为治跌打损伤之要药。','乳香；活血行气；消肿生肌；跌打损伤','中药学','活血化瘀药','乳香善活血行气止痛消肿，为伤科要药','入门'),
('中医知识库','中药','中药学','活血化瘀药','没药的功效与主治是什么？','活血止痛、消肿生肌。主治胸痹心痛、胃脘疼痛、痈疽肿痛、跌打损伤。','没药辛苦平，归心肝脾经。善于活血止痛、消肿生肌，常与乳香相须为用。','没药；活血止痛；消肿生肌；乳香没药相须','中药学','活血化瘀药','没药善活血止痛消肿，常与乳香相须为用','入门'),
('中医知识库','中药','中药学','活血化瘀药','王不留行的功效与主治是什么？','活血通经、下乳消肿。主治经闭痛经、乳汁不下、乳痈肿痛。','王不留行苦平，归肝胃经。善于活血通经、下乳消肿，为治乳汁不下之要药。','王不留行；活血通经；下乳消肿；通乳要药','中药学','活血化瘀药','王不留行善活血通经下乳，为通乳之要药','入门'),

-- 化痰止咳药补充
('中医知识库','中药','中药学','化痰止咳药','桔梗的功效与主治是什么？','宣肺利咽、祛痰排脓。主治咳嗽痰多、胸闷不畅、咽喉肿痛、失音、肺痈吐脓。','桔梗苦辛平，归肺经。善于开宣肺气、祛痰利咽，为肺经之引经药。','桔梗；宣肺利咽；祛痰排脓；肺经引经药','中药学','化痰止咳药','桔梗善宣肺利咽祛痰，为肺经之引经药','入门'),
('中医知识库','中药','中药学','化痰止咳药','川贝母的功效与主治是什么？','清热润肺、化痰止咳、散结消肿。主治肺热燥咳、干咳少痰、阴虚劳嗽、瘰疬乳痈。','川贝母苦甘微寒，归心肺经。善于润肺止咳，为治肺热燥咳之要药。','川贝母；清热润肺；化痰止咳；润肺要药','中药学','化痰止咳药','川贝母善润肺止咳，为治肺热燥咳之要药','入门'),
('中医知识库','中药','中药学','化痰止咳药','瓜蒌的功效与主治是什么？','清热涤痰、宽胸散结、润肠通便。主治肺热咳嗽、痰浊黄稠、胸痹心痛、结胸痞满、肠燥便秘。','瓜蒌甘微苦寒，归肺胃大肠经。善于清热化痰、宽胸散结。瓜蒌皮清热化痰，瓜蒌仁润肠通便。','瓜蒌；清热涤痰；宽胸散结；润肠通便','中药学','化痰止咳药','瓜蒌善清热化痰宽胸散结，皮化痰仁润肠','入门'),
('中医知识库','中药','中药学','化痰止咳药','苦杏仁的功效与主治是什么？','降气止咳平喘、润肠通便。主治咳嗽气喘、胸满痰多、肠燥便秘。','苦杏仁苦微温，归肺大肠经。善于降气止咳平喘，为治咳嗽气喘之要药。有小毒，用量不宜过大。','苦杏仁；降气止咳；平喘；润肠通便；有小毒','中药学','化痰止咳药','苦杏仁善降气止咳平喘，为治咳喘之要药，有小毒','入门'),
('中医知识库','中药','中药学','化痰止咳药','紫苏子的功效与主治是什么？','降气化痰、止咳平喘、润肠通便。主治痰壅气逆、咳嗽气喘、肠燥便秘。','紫苏子辛温，归肺大肠经。善于降气化痰止咳平喘，为治痰壅气逆之要药。','紫苏子；降气化痰；止咳平喘','中药学','化痰止咳药','紫苏子善降气化痰平喘，为治痰壅气逆之要药','入门'),
('中医知识库','中药','中药学','化痰止咳药','百部的功效与主治是什么？','润肺止咳、杀虫灭虱。主治新久咳嗽、百日咳、肺痨咳嗽、头虱体虱。','百部甘苦微温，归肺经。善于润肺止咳，无论新久咳嗽均可应用。又能杀虫灭虱。','百部；润肺止咳；杀虫灭虱；新久咳嗽','中药学','化痰止咳药','百部善润肺止咳杀虫，无论新久咳嗽均可用','入门'),
('中医知识库','中药','中药学','化痰止咳药','款冬花的功效与主治是什么？','润肺下气、止咳化痰。主治新久咳嗽、喘咳痰多、劳嗽咳血。','款冬花辛微苦温，归肺经。善于润肺下气止咳化痰，为治咳嗽之常用药。','款冬花；润肺下气；止咳化痰','中药学','化痰止咳药','款冬花善润肺下气止咳，为治咳嗽常用药','入门'),
('中医知识库','中药','中药学','化痰止咳药','枇杷叶的功效与主治是什么？','清肺止咳、降逆止呕。主治肺热咳嗽、气逆喘急、胃热呕逆、烦热口渴。','枇杷叶苦微寒，归肺胃经。善于清肺止咳、降逆止呕。需刷去毛用。','枇杷叶；清肺止咳；降逆止呕；去毛用','中药学','化痰止咳药','枇杷叶善清肺止咳降逆止呕，需去毛使用','入门'),
('中医知识库','中药','中药学','化痰止咳药','桑白皮的功效与主治是什么？','泻肺平喘、利水消肿。主治肺热喘咳、水肿胀满、面目浮肿。','桑白皮甘寒，归肺经。善于泻肺中水气、平喘止咳，又能利水消肿。','桑白皮；泻肺平喘；利水消肿','中药学','化痰止咳药','桑白皮善泻肺平喘利水消肿','入门'),
('中医知识库','中药','中药学','化痰止咳药','白果的功效与主治是什么？','敛肺定喘、止带缩尿。主治哮喘痰嗽、带下白浊、遗尿尿频。','白果甘苦涩平，归肺经。善于敛肺定喘止带，有毒，不可多食。','白果；敛肺定喘；止带缩尿；有毒','中药学','化痰止咳药','白果善敛肺定喘，有毒不可多食','入门'),

-- 安神药补充
('中医知识库','中药','中药学','安神药','远志的功效与主治是什么？','安神益智、祛痰开窍、消散痈肿。主治失眠多梦、健忘惊悸、神志恍惚、咳痰不爽。','远志苦辛微温，归心肾肺经。善于安神益智、交通心肾，为治失眠健忘之要药。','远志；安神益智；祛痰开窍；交通心肾','中药学','安神药','远志善安神益智交通心肾，为治失眠健忘之要药','入门'),
('中医知识库','中药','中药学','安神药','柏子仁的功效与主治是什么？','养心安神、润肠通便。主治虚烦失眠、心悸怔忡、肠燥便秘。','柏子仁甘平，归心肾大肠经。善于养心安神，与酸枣仁相须为用。又能润肠通便。','柏子仁；养心安神；润肠通便','中药学','安神药','柏子仁善养心安神润肠通便','入门'),
('中医知识库','中药','中药学','安神药','龙骨的功效与主治是什么？','镇惊安神、平肝潜阳、收敛固涩。主治心神不安、心悸失眠、惊痫癫狂、肝阳眩晕。','龙骨甘涩平，归心肝肾经。善于镇惊安神、平肝潜阳，煅后收敛固涩。','龙骨；镇惊安神；平肝潜阳；收敛固涩','中药学','安神药','龙骨善镇惊安神平肝潜阳，煅用收敛固涩','入门'),
('中医知识库','中药','中药学','安神药','合欢皮的功效与主治是什么？','解郁安神、活血消肿。主治心神不安、忧郁失眠、肺痈疮肿、跌打损伤。','合欢皮甘平，归心肝经。善于解郁安神，为治忧郁失眠之要药。','合欢皮；解郁安神；活血消肿；解郁要药','中药学','安神药','合欢皮善解郁安神，为治情志不遂之失眠要药','入门'),

-- 平肝熄风药补充
('中医知识库','中药','中药学','平肝熄风药','石决明的功效与主治是什么？','平肝潜阳、清肝明目。主治肝阳上亢之头痛眩晕、肝火上炎之目赤肿痛。','石决明咸寒，归肝经。善于平肝潜阳、清肝明目，为治肝阳眩晕之要药。','石决明；平肝潜阳；清肝明目；肝阳眩晕','中药学','平肝熄风药','石决明善平肝潜阳明目，为治肝阳眩晕之要药','入门'),
('中医知识库','中药','中药学','平肝熄风药','牡蛎的功效与主治是什么？','重镇安神、潜阳补阴、软坚散结。主治心神不安、惊悸失眠、肝阳眩晕、痰核瘰疬。','牡蛎咸微寒，归肝肾胆经。善于重镇安神、潜阳补阴，又能软坚散结。煅用收敛固涩。','牡蛎；重镇安神；潜阳补阴；软坚散结','中药学','平肝熄风药','牡蛎善重镇安神潜阳软坚，煅用收敛固涩','入门'),
('中医知识库','中药','中药学','平肝熄风药','全蝎的功效与主治是什么？','息风止痉、通络止痛、解毒散结。主治急慢惊风、癫痫抽搐、中风面瘫、偏正头痛、疮疡肿毒。','全蝎辛平有毒，归肝经。善于息风止痉、通络止痛，为治痉挛抽搐之要药。','全蝎；息风止痉；通络止痛；有毒','中药学','平肝熄风药','全蝎善息风止痉通络，为治痉挛抽搐之要药','中级'),
('中医知识库','中药','中药学','平肝熄风药','蜈蚣的功效与主治是什么？','息风止痉、攻毒散结、通络止痛。主治急慢惊风、癫痫抽搐、疮疡肿毒、顽痹疼痛。','蜈蚣辛温有毒，归肝经。善于息风止痉，与全蝎相须为用，止痉力更强。','蜈蚣；息风止痉；攻毒散结；通络止痛','中药学','平肝熄风药','蜈蚣善息风止痉攻毒通络，与全蝎相须为用','中级'),
('中医知识库','中药','中药学','平肝熄风药','地龙的功效与主治是什么？','清热定惊、通络平喘、利尿。主治高热惊痫、中风半身不遂、肺热喘咳、小便不利。','地龙咸寒，归肝脾膀胱经。善于清热息风、通络止痉，又能平喘利尿。','地龙；清热定惊；通络平喘；利尿','中药学','平肝熄风药','地龙善清热息风通络，又能平喘利尿','入门'),

-- 补虚药补充
('中医知识库','中药','中药学','补气药','西洋参的功效与主治是什么？','补气养阴、清热生津。主治气虚阴亏、虚热烦倦、咳喘痰血、内热消渴。','西洋参苦微甘寒，归心肺肾经。善于补气养阴、清火生津。与人参相比，补而不燥。','西洋参；补气养阴；清热生津；补而不燥','中药学','补虚药','西洋参善补气养阴清火生津，补而不燥','入门'),
('中医知识库','中药','中药学','补气药','山药的功效与主治是什么？','补脾养胃、生津益肺、补肾涩精。主治脾虚食少、久泻不止、肺虚喘咳、肾虚遗精。','山药甘平，归脾肺肾经。药性平和，既能补气，又能养阴，为平补脾胃之常用药。','山药；补脾养胃；生津益肺；补肾涩精；平补','中药学','补虚药','山药药性平和，为平补脾肺肾之常用药食两用品','入门'),
('中医知识库','中药','中药学','补气药','甘草的功效与主治是什么？','补脾益气、清热解毒、祛痰止咳、缓急止痛、调和诸药。主治脾胃虚弱、倦怠乏力、咳嗽痰多。','甘草甘平，归心肺脾胃经。为应用最广泛的中药之一，有"国老"之称。善调和诸药，解毒缓急。','甘草；补脾益气；调和诸药；国老','中药学','补虚药','甘草有国老之称，善补脾益气调和诸药','入门'),
('中医知识库','中药','中药学','补气药','白术的功效补充有哪些？','除健脾益气外，白术还有哪些临床应用？白术可用于：安胎（治胎动不安）、止汗（治表虚自汗）、燥湿（治痰饮水肿）。','白术甘苦温，归脾胃经。为健脾第一要药。不同炮制品功效有别：生白术燥湿力强，炒白术健脾力强，焦白术止泻力强。','白术；健脾安胎；止汗；燥湿利水','中药学','补虚药','白术为健脾第一要药，兼能燥湿安胎止汗','入门'),
('中医知识库','中药','中药学','补血药','白芍的功效与主治是什么？','养血调经、敛阴止汗、柔肝止痛、平抑肝阳。主治血虚萎黄、月经不调、自汗盗汗、胁痛腹痛。','白芍苦酸微寒，归肝脾经。善于养血敛阴、柔肝止痛。与赤芍相比，白芍偏于养血敛阴。','白芍；养血调经；敛阴止汗；柔肝止痛','中药学','补虚药','白芍善养血敛阴柔肝止痛，与赤芍一补一泻','入门'),
('中医知识库','中药','中药学','补血药','阿胶的功效与主治是什么？','补血滋阴、润燥止血。主治血虚萎黄、眩晕心悸、肌痿无力、心烦不眠、虚风内动、肺燥咳嗽。','阿胶甘平，归肺肝肾经。为补血滋阴之要药，善治血虚诸证。烊化兑服。','阿胶；补血滋阴；润燥止血；烊化兑服','中药学','补虚药','阿胶为补血滋阴之要药，烊化兑服','入门'),
('中医知识库','中药','中药学','补阴药','北沙参的功效与主治是什么？','养阴清肺、益胃生津。主治肺热燥咳、阴虚劳嗽、热病伤津、口干口渴。','北沙参甘微苦微寒，归肺胃经。善于养阴清肺、益胃生津，为治肺胃阴虚之常用药。','北沙参；养阴清肺；益胃生津','中药学','补虚药','北沙参善养阴清肺益胃生津，为肺胃阴虚常用药','入门'),
('中医知识库','中药','中药学','补阴药','百合的功效与主治是什么？','养阴润肺、清心安神。主治阴虚燥咳、劳嗽咳血、虚烦惊悸、失眠多梦。','百合甘微寒，归心肺经。善于养阴润肺止咳，又能清心安神。为药食两用之品。','百合；养阴润肺；清心安神；药食两用','中药学','补虚药','百合善养阴润肺清心安神，为药食两用佳品','入门'),
('中医知识库','中药','中药学','补阴药','石斛的功效与主治是什么？','益胃生津、滋阴清热。主治热病津伤、口干烦渴、胃阴不足、食少干呕、病后虚热。','石斛甘微寒，归胃肾经。善于养胃生津、滋阴清热，为治胃阴不足之要药。','石斛；益胃生津；滋阴清热；养胃要药','中药学','补虚药','石斛善益胃生津滋阴清热，为养胃阴之要药','入门'),
('中医知识库','中药','中药学','补阴药','龟甲的功效与主治是什么？','滋阴潜阳、益肾健骨、养血补心。主治阴虚阳亢、头晕目眩、骨蒸潮热、盗汗遗精、筋骨痿软。','龟甲甘咸寒，归肝肾心经。善于滋阴潜阳，为治阴虚阳亢之要药。又能益肾健骨。','龟甲；滋阴潜阳；益肾健骨；养血补心','中药学','补虚药','龟甲善滋阴潜阳益肾健骨，为滋阴要药','中级'),
('中医知识库','中药','中药学','补阴药','鳖甲的功效与主治是什么？','滋阴潜阳、退热除蒸、软坚散结。主治阴虚发热、骨蒸劳热、虚风内动、癥瘕积聚。','鳖甲咸微寒，归肝肾经。善于滋阴退热，又能软坚散结。用于阴虚发热、癥瘕痞块。','鳖甲；滋阴潜阳；退热除蒸；软坚散结','中药学','补虚药','鳖甲善滋阴退热软坚散结','中级'),
('中医知识库','中药','中药学','补阳药','淫羊藿的功效与主治是什么？','补肾阳、强筋骨、祛风湿。主治肾阳虚衰、阳痿尿频、筋骨痿软、风湿痹痛。','淫羊藿辛甘温，归肝肾经。善于补肾壮阳，为治肾阳不足之常用药。又能祛风除湿。','淫羊藿；补肾壮阳；强筋骨；祛风湿','中药学','补虚药','淫羊藿善补肾壮阳强筋骨，为补肾常用药','入门'),
('中医知识库','中药','中药学','补阳药','杜仲的功效与主治是什么？','补肝肾、强筋骨、安胎。主治肾虚腰痛、筋骨无力、妊娠漏血、胎动不安。','杜仲甘温，归肝肾经。善于补肝肾、强筋骨，为治肾虚腰痛之要药。炒用效果更佳。','杜仲；补肝肾；强筋骨；安胎；腰痛要药','中药学','补虚药','杜仲善补肝肾强筋骨，为治肾虚腰痛之要药','入门'),
('中医知识库','中药','中药学','补阳药','补骨脂的功效与主治是什么？','补肾助阳、温脾止泻、纳气平喘。主治肾阳不足、阳痿遗精、腰膝冷痛、五更泄泻。','补骨脂辛苦温，归肾脾经。善于补肾助阳，又能温脾止泻、纳气平喘。','补骨脂；补肾助阳；温脾止泻；纳气平喘','中药学','补虚药','补骨脂善补肾助阳温脾止泻纳气平喘','入门'),
('中医知识库','中药','中药学','补阳药','菟丝子的功效与主治是什么？','补肾益精、养肝明目、固精缩尿、止泻安胎。主治肾虚腰痛、阳痿遗精、尿频遗尿、目昏耳鸣。','菟丝子甘温，归肝肾脾经。药性平和，既能补肾阳，又能益肾精，为平补阴阳之品。','菟丝子；补肾益精；养肝明目；平补阴阳','中药学','补虚药','菟丝子药性平和，为平补阴阳之品','入门'),
('中医知识库','中药','中药学','补阳药','冬虫夏草的功效与主治是什么？','补肾益肺、止血化痰。主治肾虚精亏、阳痿遗精、腰膝酸痛、久咳虚喘、劳嗽痰血。','冬虫夏草甘平，归肾肺经。既能补肾阳，又能益肺阴，为平补肺肾之珍品。价格昂贵。','冬虫夏草；补肾益肺；止血化痰；平补肺肾','中药学','补虚药','冬虫夏草为平补肺肾之珍品，补肾阳益肺阴','中级'),

-- 收涩药补充
('中医知识库','中药','中药学','收涩药','乌梅的功效与主治是什么？','敛肺止咳、涩肠止泻、安蛔止痛、生津止渴。主治肺虚久咳、久泻久痢、蛔厥腹痛、虚热消渴。','乌梅酸涩平，归肝脾肺大肠经。酸涩收敛，善于敛肺涩肠、安蛔生津。为治蛔厥之要药。','乌梅；敛肺止咳；涩肠止泻；安蛔止痛','中药学','收涩药','乌梅酸涩收敛，善安蛔止痛敛肺涩肠','入门'),
('中医知识库','中药','中药学','收涩药','山茱萸的功效与主治是什么？','补益肝肾、收涩固脱。主治眩晕耳鸣、腰膝酸痛、阳痿遗精、遗尿尿频、月经过多、大汗虚脱。','山茱萸酸涩微温，归肝肾经。既能补益肝肾，又能收敛固涩，为补敛并俱之品。','山茱萸；补益肝肾；收涩固脱；补敛并俱','中药学','收涩药','山茱萸补敛并俱，既补肝肾又收敛固涩','入门'),
('中医知识库','中药','中药学','收涩药','莲子肉的功效与主治是什么？','补脾止泻、止带、益肾涩精、养心安神。主治脾虚泄泻、带下、遗精、心悸失眠。','莲子甘涩平，归脾肾心经。药性平和，既能补脾止泻，又能益肾固精、养心安神。','莲子；补脾止泻；益肾涩精；养心安神','中药学','收涩药','莲子药性平和，补脾益肾养心三脏同调','入门'),
('中医知识库','中药','中药学','收涩药','芡实的功效与主治是什么？','益肾固精、补脾止泻、除湿止带。主治遗精滑精、遗尿尿频、脾虚久泻、白浊带下。','芡实甘涩平，归脾肾经。药性平和，补中兼涩，为健脾止泻、益肾固精之常用药。','芡实；益肾固精；补脾止泻；除湿止带','中药学','收涩药','芡实补中兼涩，为健脾益肾之常用药','入门'),
('中医知识库','中药','中药学','收涩药','海螵蛸的功效与主治是什么？','收敛止血、涩精止带、制酸止痛、收湿敛疮。主治崩漏下血、遗精带下、胃痛吞酸、湿疹溃疡。','海螵蛸咸涩微温，归肝肾经。善于收敛止血、制酸止痛，为治胃痛吞酸之常用药。','海螵蛸；收敛止血；制酸止痛；涩精止带','中药学','收涩药','海螵蛸善收敛止血制酸止痛，为胃痛常用药','入门');
